const l=[{id:"M01",title:"Ryan et Deci · 2000 · Théorie de l’autodétermination",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"La motivation peut venir de valeurs que tu as choisies, sans plaisir à agir. Cette théorie propose trois besoins fondamentaux : autonomie, compétence et lien aux autres.",limitation:"Théorie et revue narrative, pas un essai des questions d’ODA. L’autonomie ne signifie pas l’indépendance. Récompenses et obligations n’empêchent pas forcément de choisir un objectif pour soi."},{id:"M02",title:"Ntoumanis et collègues · 2021 · Programmes de santé soutenant les besoins psychologiques",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 études montrent des bénéfices moyens modestes sur la motivation autonome et, plus tard, les comportements de santé. L’amélioration immédiate de la santé physique n’était pas statistiquement significative.",limitation:"Programmes de santé à plusieurs composantes, avec de fortes différences entre études et des limites méthodologiques. Une question sur les valeurs ne reproduit pas ces programmes et ne démontre pas un effet pour tout objectif."},{id:"M03",title:"Duckworth et collègues · 2013 · Protocole scolaire MCII",url:"https://www.researchgate.net/publication/256294319_From_Fantasy_to_Action_Mental_Contrasting_With_Implementation_Intentions_MCII_Improves_Academic_Performance_in_Children",type:"research",finding:"Un essai auprès de 77 élèves de cinquième année de primaire associait trois séances d’une heure en petits groupes à des exercices répétés : résultat, obstacle, réponse. Certains résultats scolaires se sont améliorés.",limitation:"Une seule école ; les différences ultérieures entre groupes n’étaient pas significatives. Accompagnement et durée adaptés aux enfants. Aucun effet établi pour un bref exercice sur téléphone chez l’adulte."},{id:"M04",title:"Cerasoli, Nicklin et Ford · 2014 · Motivation et incitations",url:"https://selfdeterminationtheory.org/wp-content/uploads/2017/06/2014_Cerasoli_Intrinsic.pdf",type:"research",finding:"Dans 183 échantillons, motivation intrinsèque et incitations étaient toutes deux liées à la performance. Les liens différaient selon la qualité ou la quantité produite.",limitation:"Ces associations, variables selon les études, ne donnent pas de règle universelle sur les récompenses. Elles ne montrent pas qu’un objectif valorisé par les autres serait forcément inauthentique."},{id:"M05",title:"Lally et collègues · 2010 · Modélisation de la formation des habitudes",url:"https://www.flexyourbrain.com/wp-content/uploads/2015/10/UL-STUDY-66-Days-IJSP_998-1009.pdf",type:"research",finding:"Pour 39 courbes bien ajustées, le délai médian estimé pour atteindre 95 pour cent du plateau d’automaticité était de 66 jours. Une occasion manquée n’a pas sensiblement perturbé le processus modélisé.",limitation:"Observation sur 84 jours ; les 254 jours étaient extrapolés. Ce ne sont ni des dates d’achèvement observées, ni un calendrier universel, ni des données sur les longues interruptions."},{id:"M07",title:"Wood et Rünger · 2016 · Psychologie des habitudes",url:"https://dornsife.usc.edu/wendy-wood/wp-content/uploads/sites/183/2023/10/wood.runger.2016.pdf",type:"research",finding:"Répéter une réponse dans un contexte récurrent peut favoriser l’apprentissage d’une habitude. Objectifs délibérés et réactions habituelles peuvent coexister.",limitation:"Revue narrative, pas un essai du minimum ou du repère proposé par ODA. Un repère ne garantit pas l’action ; une petite pratique ne s’allonge pas forcément."},{id:"M08",title:"Gollwitzer et Sheeran · 2006 · Plans « si… alors… »",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"Sur 94 tests indépendants, les plans précis « si… alors… » ont amélioré en moyenne l’atteinte des objectifs. La taille d’effet standardisée historique était d = 0.65.",limitation:"Données anciennes et variées. Ni amélioration de 65 pour cent, ni exécution garantie, ni valeur de référence pour un rappel d’application."},{id:"M10",title:"Wang, Wang et Gai · 2021 · Contraste mental et planification",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"21 articles et 24 effets indépendants montrent un bénéfice moyen faible à modéré sur l’atteinte des objectifs avec un plan associant résultat, obstacle et réponse.",limitation:"Différences entre études et indices de biais de publication limitent l’estimation. Aucun souhait garanti, aucune preuve d’action sur les événements extérieurs, aucune validation de tous les formats WOOP."},{id:"M13",title:"Harkin et collègues · 2016 · Suivi des progrès",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"Dans 138 études randomisées, les interventions de suivi ont amélioré en moyenne l’atteinte des objectifs.",limitation:"Objectifs et méthodes variés. Les associations observées n’isolent pas l’effet causal de noter ou partager. Aucun rythme hebdomadaire optimal ni partage public obligatoire n’est établi."},{id:"M15",title:"Fogg · Consignes de conception Tiny Habits",url:"https://tinyhabits.com/design/",type:"technique",finding:"Cette méthode de praticien associe une routine existante à un tout petit comportement. Elle recommande de modifier les associations qui ne fonctionnent pas.",limitation:"Cette page ne fournit aucune estimation contrôlée validant toute la méthode, la nécessité de célébrer, une durée optimale inférieure à une minute ou une progression inévitable."},{id:"M20",title:"NIMH · Prendre soin de sa santé mentale",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Des symptômes persistants, sévères ou éprouvants, une perte d’intérêt ou l’impossibilité d’accomplir les activités habituelles justifient une aide professionnelle. Un danger urgent exige une aide immédiate.",limitation:"Conseils publics, pas un essai d’efficacité d’ODA ni un diagnostic fondé sur le manque de motivation. En cas d’inquiétude, inutile d’attendre deux semaines, une série de réussites ou la fin du cours."},{id:"motivation-sdt",title:"Ryan et Deci · 2000 · Théorie de l’autodétermination",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"La motivation peut venir de valeurs que tu as choisies, sans plaisir à agir. Cette théorie propose trois besoins fondamentaux : autonomie, compétence et lien aux autres.",limitation:"Théorie et revue narrative, pas un essai des questions d’ODA. L’autonomie ne signifie pas l’indépendance. Récompenses et obligations n’empêchent pas forcément de choisir un objectif pour soi."},{id:"motivation-sdt-meta",title:"Ntoumanis et collègues · 2021 · Programmes de santé soutenant les besoins psychologiques",url:"https://selfdeterminationtheory.org/wp-content/uploads/2020/05/2020_NtoumanisEtAl_MetaAnalysisHealth.pdf",type:"research",finding:"73 études montrent des bénéfices moyens modestes sur la motivation autonome et, plus tard, les comportements de santé. L’amélioration immédiate de la santé physique n’était pas statistiquement significative.",limitation:"Programmes de santé à plusieurs composantes, avec de fortes différences entre études et des limites méthodologiques. Une question sur les valeurs ne reproduit pas ces programmes et ne démontre pas un effet pour tout objectif."},{id:"M16",title:"Fogg · Consignes Tiny Habits pour un geste positif",url:"https://tinyhabits.com/rewire/",type:"technique",finding:"Fogg recommande un geste positif immédiat, choisi par la personne, après un tout petit comportement.",limitation:"Page de praticien sans estimation contrôlée. La nécessité de célébrer, l’accélération des connexions neuronales et l’équivalence avec une case cochée n’ont pas été établies indépendamment."}],i=[{schemaVersion:2,revision:2,id:"motivation-1",courseId:"motivation",locale:"fr",title:"La tâche te rebute ? Examine ton objectif.",goal:"Décide si cet objectif vaut l’effort demandé, puis essaie une action qui le sert.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Cet objectif te pèse déjà ? Regarde ce que l’effort pourrait changer dans ton quotidien.",reason:{id:"motivation-1-reason",label:"Quel changement mérite le temps et l’énergie demandés chaque semaine ?",kind:"text",maxLength:160,optional:!0,suggestions:["Ouvrir des possibilités à ma famille","Faire une place à ma curiosité","Assumer une responsabilité choisie"]},why:{id:"motivation-1-why",label:"Quel changement mérite le temps et l’énergie demandés chaque semaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Tu peux choisir une tâche sans aimer la faire. Étudier pour un revenu stable, aider un proche ou obtenir un diplôme peut compter pour toi. Plaisir et choix personnel sont deux questions différentes. L’approbation des autres ne rend pas forcément ton objectif moins personnel.","Regarde ce que cet objectif changerait au quotidien et son coût cette semaine. Garde-le, adapte-le, reporte-le ou abandonne-le. Si tu le gardes, essaie une action utile au prochain créneau disponible. Tu testes un choix, sans prétendre révéler tes véritables motivations."],example:{title:"Leïla essaie une question",text:"À 19 h, Leïla met en balance son diplôme et le temps en famille. Les cours lui déplaisent, mais les débouchés comptent. Elle garde l’objectif et répond à une question d’entraînement à la table de la cuisine. Sa réponse reste incomplète. Elle note l’essai et un autre créneau, sans prétendre avoir aimé étudier."}},move:{invitation:"Choisis ton objectif et l’action concrète qui le sert, puis adapte un exemple.",instructions:["Adapte les exemples : aide quotidienne, travail, relations ou autre action choisie.","Enregistre une date disponible, un repère de départ et un lieu."],prompts:[{id:"motivation-1-0",label:"À quoi choisis-tu de renoncer pour cet objectif ?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Exemple : répondre à la première question du diplôme","Confirmer avec Camille quand chercher son enfant demain","Rédiger une phrase pour informer mon client","Poser à Alex notre question convenue"],minimum:["Répondre à cette question d’entraînement","Envoyer à Camille l’heure convenue","Écrire une première phrase utile au client","Demander à Alex comment s’est passé son rendez-vous"],cue:["Après avoir débarrassé mon assiette du dîner","À réception du SMS de Camille sur l’heure","Après ma pause de 14 h au travail","Au début de notre échange du soir convenu"],place:["À la table de ma cuisine","Dans notre conversation SMS habituelle","Sur mon ordinateur de travail","Pendant notre appel habituel"],minutes:[2,1,5],fallback:["Répondre à une question plus courte des notes","Appeler par le moyen convenu ensemble","Dicter cette phrase dans mes notes accessibles","Proposer notre échange par SMS déjà convenu"],observation:["Ma réponse et le temps qu’elle a pris","Heure envoyée ou non ; réponse notée séparément","La phrase utile rédigée pour mon client","Question posée, même sans réponse"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : répondre à la première question du diplôme",minimum:"Répondre à cette question d’entraînement",cue:"Après avoir débarrassé mon assiette du dîner",place:"À la table de ma cuisine",fallback:"Répondre à une question plus courte des notes",observation:"Ma réponse et le temps qu’elle a pris",minutes:2},{action:"Confirmer avec Camille quand chercher son enfant demain",minimum:"Envoyer à Camille l’heure convenue",cue:"À réception du SMS de Camille sur l’heure",place:"Dans notre conversation SMS habituelle",fallback:"Appeler par le moyen convenu ensemble",observation:"Heure envoyée ou non ; réponse notée séparément",minutes:1},{action:"Rédiger une phrase pour informer mon client",minimum:"Écrire une première phrase utile au client",cue:"Après ma pause de 14 h au travail",place:"Sur mon ordinateur de travail",fallback:"Dicter cette phrase dans mes notes accessibles",observation:"La phrase utile rédigée pour mon client",minutes:5},{action:"Poser à Alex notre question convenue",minimum:"Demander à Alex comment s’est passé son rendez-vous",cue:"Au début de notre échange du soir convenu",place:"Pendant notre appel habituel",fallback:"Proposer notre échange par SMS déjà convenu",observation:"Question posée, même sans réponse",minutes:2}]},suggested:{action:"Exemple : répondre à la première question du diplôme",minimum:"Répondre à cette question d’entraînement",minutes:2,cueHint:"Après avoir débarrassé mon assiette du dîner",placeHint:"À la table de ma cuisine",obstacleHint:"Exemple : cette question empiète sur le temps en famille",fallbackHint:"Répondre à une question plus courte des notes",observationHint:"Ma réponse et le temps qu’elle a pris"},stopRule:"Ne force pas en cas de maladie, de danger ou de difficultés persistantes au quotidien. Tu peux demander du soutien dès maintenant.",accessibleAlternative:"Utilise l’audio, la dictée, des outils adaptés, une aide convenue ou une pause explicite."},result:{question:"As-tu essayé l’action que tu avais choisie ?",observationPrompt:"Qu’as-tu fait concrètement, et quel effort cela t’a demandé ?"},judgment:{primary:{id:"motivation-1-decision",scenario:"Leïla n’aime pas préparer son diplôme. Elle veut des débouchés plus stables pour sa famille. Ses collègues valorisent aussi ce diplôme.",question:"Comment vérifier si elle veut garder cet objectif ?",options:[{id:"motivation-1-endorse",text:"Vérifier si le bénéfice et le temps demandé lui conviennent, puis répondre à une question d’entraînement.",feedback:"Ce choix distingue le déplaisir du choix personnel et teste une action faisable. La reconnaissance peut accompagner une raison choisie. Leïla reste libre d’adapter ou de reporter cet objectif si son coût ne lui convient pas."},{id:"motivation-1-interest",text:"Essayer un objectif plus agréable pendant une semaine, puis décider si ce diplôme lui correspond encore.",feedback:"Explorer un autre intérêt peut aider. Mais le plaisir seul ne dit pas si Leïla choisit ce diplôme pour elle. Examine d’abord le bénéfice et le coût qu’elle accepte. Une tâche importante peut rester désagréable."},{id:"motivation-1-advice",text:"Demander aux collègues diplômés quelle formation ils choisiraient, puis suivre leur recommandation.",feedback:"Les collègues peuvent préciser les possibilités et les exigences. Ils ne peuvent pas arbitrer à la place de Leïla. Avant d’adopter leur objectif, elle doit identifier sa propre raison et le temps qu’elle peut y consacrer."}],bestOptionId:"motivation-1-endorse"}},carry:{takeaway:"Un objectif choisi peut être difficile. Évalue son intérêt et son coût, puis essaie l’action correspondante.",followUp:{questionId:"motivation-1-return",question:"Cet essai a-t-il servi ta raison de départ ? L’effort demandé te convient-il encore ?",observationPrompt:"Qu’as-tu fait concrètement, et quel effort cela t’a demandé ?",adjustmentPrompt:"Quel seul changement rendrait le prochain essai plus adapté ?"}},goDeeper:{sections:[{heading:"Choisir ne veut pas dire aimer",paragraphs:["La théorie de l’autodétermination de Ryan et Deci distingue le plaisir intrinsèque des raisons que la personne fait siennes. Un objectif extérieur à l’activité peut compter : diplôme, revenu, aide à un proche ou responsabilité partagée. Le geste peut rester ennuyeux. L’autonomie désigne un sentiment de choix, pas l’absence d’obligations ou d’influences. Leur article de 2000 présente une théorie et une revue narrative. Il ne teste pas cette leçon. [M01]","Garder, adapter, reporter ou abandonner l’objectif est ici un exercice de réflexion proposé par ODA. Ce choix ne révèle pas des motivations pures et ne certifie pas l’authenticité d’un objectif. La vaste méta-analyse de Cerasoli et collègues relie motivation intrinsèque et incitations à la performance, avec des variations selon la qualité et la quantité produites. Elle ne classe pas toutes les récompenses comme bonnes ou mauvaises. [M04] Tu peux reconnaître plusieurs motivations et décider si l’action sert la vie que tu souhaites."]},{heading:"Une question ne remplace pas un programme",paragraphs:["Ntoumanis et collègues ont regroupé 73 études de programmes de santé inspirés de l’autodétermination. Ils ont trouvé des bénéfices moyens modestes sur la motivation autonome et les comportements de santé ultérieurs. Les programmes combinaient plusieurs soutiens et les résultats variaient beaucoup. L’amélioration immédiate de la santé physique n’était pas statistiquement significative. Ces résultats n’établissent pas le même bénéfice pour tout objectif professionnel, scolaire ou personnel. [M02]","Une seule question sur tes raisons ne reproduit pas ces programmes. Ici, ta raison guide un essai concret : un objectif, une action, les faits notés honnêtement et une prochaine occasion. Ce premier essai sert à examiner la faisabilité, l’accès et l’effort, sans exiger d’enthousiasme. Garde les détails pour toi si tu préfères. Les leçons suivantes gardent cette direction et testent un minimum utile, un repère praticable et une réponse à un obstacle réel. Faire une pause ou demander du soutien reste valable si l’objectif ou tes conditions demandent de l’attention."]}],sourceIds:["M01","M04","M02"]}},{schemaVersion:2,revision:2,id:"motivation-2",courseId:"motivation",locale:"fr",title:"Encore un livre ouvert sans lire ?",goal:"Essaie une version courte de ton action, qui reste utile.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Livre ouvert, aucune phrase lue ? Réduis la partie utile jusqu’à pouvoir la faire.",reason:{id:"motivation-2-useful-unit-cost",label:"Quelle préparation peux-tu arrêter pour laisser une place à l’action utile ?",kind:"text",maxLength:160,optional:!0,suggestions:["Lire une phrase au lieu de rouvrir","Écrire au lieu de réorganiser","Raccourcir le geste, garder son utilité"]},why:{id:"motivation-2-why",label:"Quel minimum utile servirait ta raison de départ ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Garde l’objectif choisi. Réduis l’action pour aujourd’hui, sans enlever ce qui le sert. Mets le livre à portée de main, puis lis une phrase. Ouvre ta candidature, puis écris une phrase utile. Installer le matériel, c’est préparer. La phrase, c’est l’action à tester.","Les recherches sur les habitudes décrivent des réponses répétées dans des contextes récurrents. Elles ne montrent pas que chaque petit départ mène à davantage, ni qu’une case cochée agit comme une célébration. Ton minimum peut rester petit. Essaie-le, note les faits, puis vérifie si cette quantité sert encore ta raison."],example:{title:"Leïla raccourcit la question",text:"Mardi après le dîner, Leïla a deux minutes pour le même diplôme. Elle installe ses notes, puis répond à une courte question d’entraînement. Elle s’arrête : le temps en famille compte aussi. Sa réponse demande une correction. Elle note la réponse comme travail et les notes installées comme préparation, sans prolonger la séance."}},move:{invitation:"Garde l’action enregistrée et raccourcis sa partie utile avant d’enregistrer.",instructions:["Garde ton action et un cadre praticable ; modifie seulement le minimum utile.","Mets le matériel à portée de main, puis fais ce minimum."],prompts:[],suggestions:{action:["Exemple : répondre à la prochaine question du diplôme","Rédiger le paragraphe de candidature enregistré","Faire le nettoyage de cuisine convenu"],minimum:["Répondre à la première partie de cette question","Écrire une phrase utilisable de ce paragraphe","Laver les deux tasses convenues"],cue:["Après avoir débarrassé mon assiette du dîner","Après ma pause de 14 h au travail","Après notre repas partagé"],place:["À la table de ma cuisine","Sur mon ordinateur de travail","À mon évier accessible"],minutes:[2,1],fallback:["Dicter la première partie avec mes notes accessibles","Dicter une phrase utilisable dans mes notes","Choisir un autre nettoyage accessible, convenu ensemble"],observation:["Réponse donnée ou matériel seulement préparé","Phrase écrite ou fichier seulement ouvert","Tâche convenue faite ou produits seulement installés"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : répondre à la prochaine question du diplôme",minimum:"Répondre à la première partie de cette question",cue:"Après avoir débarrassé mon assiette du dîner",place:"À la table de ma cuisine",fallback:"Dicter la première partie avec mes notes accessibles",observation:"Réponse donnée ou matériel seulement préparé",minutes:2},{action:"Rédiger le paragraphe de candidature enregistré",minimum:"Écrire une phrase utilisable de ce paragraphe",cue:"Après ma pause de 14 h au travail",place:"Sur mon ordinateur de travail",fallback:"Dicter une phrase utilisable dans mes notes",observation:"Phrase écrite ou fichier seulement ouvert",minutes:1},{action:"Faire le nettoyage de cuisine convenu",minimum:"Laver les deux tasses convenues",cue:"Après notre repas partagé",place:"À mon évier accessible",fallback:"Choisir un autre nettoyage accessible, convenu ensemble",observation:"Tâche convenue faite ou produits seulement installés",minutes:2}]},suggested:{action:"Exemple : répondre à la prochaine question du diplôme",minimum:"Répondre à la première partie de cette question",minutes:2,cueHint:"Après avoir débarrassé mon assiette du dîner",placeHint:"À la table de ma cuisine",obstacleHint:"Exemple : je prépare le matériel sans répondre",fallbackHint:"Dicter la première partie avec mes notes accessibles",observationHint:"Réponse donnée ou matériel seulement préparé"},stopRule:"Choisis une action sûre. Arrête en cas de douleur, de maladie, de besoin urgent ou d’installation inaccessible.",accessibleAlternative:"Écoute, dicte, utilise des outils adaptés, ou choisis une préparation clairement nommée et une prochaine occasion d’agir."},result:{question:"As-tu fait la partie utile de ton minimum ?",observationPrompt:"Qu’as-tu fait pour avancer, et qu’as-tu seulement préparé ?"},judgment:{primary:{id:"motivation-2-decision",scenario:"Tu veux rédiger une candidature. Depuis trois séances, tu ouvres le fichier sans rien écrire. Tu as deux minutes et connais la rubrique demandée.",question:"Quel minimum permet maintenant de tester un progrès utile ?",options:[{id:"motivation-2-bigger",text:"Réserver une séance plus longue pour que rédiger une réponse complète donne envie de commencer.",feedback:"Une séance plus longue peut aider à terminer, mais elle ne teste pas ce schéma répété : préparer sans écrire. Fais une première phrase au brouillon maintenant. Tu verras ensuite si un créneau plus long est nécessaire."},{id:"motivation-2-outline",text:"Consacrer ces deux minutes à trois idées de plan, puis rédiger la rubrique lors d’une séance plus longue.",feedback:"Un plan peut clarifier le contenu. Ici, tu connais déjà cette rubrique. Ce qui bloque à répétition, c’est commencer à rédiger. Une phrase au brouillon teste ce point maintenant. Note le plan comme une préparation."},{id:"motivation-2-sentence",text:"Écrire une phrase au brouillon pour la rubrique demandée, puis s’arrêter au temps disponible.",feedback:"Ce choix contient l’action et laisse une phrase à retravailler. Il ne garantit pas le succès de la candidature et n’exige pas de prolonger la séance. Note la phrase séparément de l’ouverture du fichier."}],bestOptionId:"motivation-2-sentence"}},carry:{takeaway:"Rends le début faisable, sans enlever ce qui fait avancer ton objectif.",followUp:{questionId:"motivation-2-return",question:"Ta version courte a-t-elle produit une action utile, ou seulement préparé le terrain ?",observationPrompt:"Qu’as-tu fait pour avancer, et qu’as-tu seulement préparé ?",adjustmentPrompt:"Quel seul changement rendrait le prochain essai plus adapté ?"}},goDeeper:{sections:[{heading:"Faire petit est un choix, pas une garantie",paragraphs:["Wood et Rünger décrivent les habitudes comme des réponses apprises dans des contextes récurrents. La répétition peut rendre une action plus automatique, sans effacer les objectifs délibérés. Leur revue n’établit pas qu’une phrase serait la quantité optimale, ni que toute petite pratique s’allongera forcément. Cette leçon propose une petite unité pour tester l’accès et l’utilité dans ta semaine réelle. [M07]","Cette unité distingue la préparation de l’action que tu veux pratiquer. Une réponse peut être vérifiée. Une phrase lue peut apporter une information. Une phrase écrite peut être corrigée. Le matériel prêt aide à démarrer, mais ne réalise aucune de ces actions. Si plusieurs petits essais ne servent jamais ta raison de départ, réexamine l’action ou l’objectif. Il te faut peut-être une autre unité, davantage de soutien ou un créneau plus long, mais disponible. Une case cochée ne suffit pas à fabriquer du progrès. [M07]"]},{heading:"La méthode du praticien a ses limites",paragraphs:["Les consignes Tiny Habits de BJ Fogg associent une routine existante à un tout petit comportement. Elles recommandent de modifier une association qui ne fonctionne pas. Il s’agit d’une technique de praticien. La page examinée ne démontre pas indépendamment que toute la méthode surpasse un simple plan avec repère, ni que chaque action doit durer moins d’une minute. [M15]","Fogg recommande aussi un geste positif immédiat, choisi par la personne. Le dossier ne trouve pas de preuve contrôlée établissant des connexions neuronales plus rapides, la nécessité de célébrer ou une case cochée aussi renforçante. [M16] Tu peux accueillir une satisfaction si elle vient, sans la fabriquer. Un récit honnête dit ce qui s’est passé. Il reste distinct de ton ressenti ensuite. Tu peux t’arrêter au minimum utile, le garder demain et adapter tes outils ou ton accès. Une quantité plus petite ne dit rien de ta valeur."]}],sourceIds:["M07","M15","M16"]}},{schemaVersion:2,revision:2,id:"motivation-3",courseId:"motivation",locale:"fr",title:"Le rappel sonne. Tu ne peux toujours pas commencer.",goal:"Teste ton minimum quand le temps, le matériel et l’accès sont disponibles.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Le rappel sonne dans le bus ? Choisis un moment où l’action est possible.",reason:{id:"motivation-3-available-setting-cost",label:"Quel créneau disponible choisiras-tu, et que déplaceras-tu pour le préserver ?",kind:"text",maxLength:160,optional:!0,suggestions:["Utiliser ma pause fixe, que je peux préserver","Déplacer une corvée sans horaire imposé","Faire assurer l’aide au proche pendant l’essai"]},why:{id:"motivation-3-why",label:"Quel moment disponible préserve du temps pour ton objectif ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ton repère doit remplir trois conditions : se présenter, attirer ton attention et permettre l’action. Après avoir déposé les enfants à l’école, tu pars travailler ? Ce repère ne permet pas de travailler à ton bureau. Garde ton minimum utile, dans un cadre qui le permet.","Un plan précis « si… alors… » peut aider à passer à l’action. Répéter dans un contexte récurrent peut favoriser une habitude, sans délai universel. Aujourd’hui, teste le repère, sans chercher l’automatisme. Note lesquelles des trois conditions étaient réunies et laquelle demande un ajustement."],example:{title:"Leïla trouve un créneau praticable",text:"Leïla voulait répondre après avoir déposé son enfant à l’école, mais partait travailler sans ses notes. Mercredi, elle déplace la même question après le dîner, à la table de la cuisine. Le repère se présente, elle le remarque et répond avant de débarrasser. Cette réponse est utile. L’ancien créneau impraticable reste noté."}},move:{invitation:"Garde la même action ; choisis un événement et un lieu disponibles.",instructions:["Vérifie si le repère se présente, se remarque et permet l’action enregistrée.","Choisis la date et vérifie que le matériel ou l’accès sera disponible."],prompts:[],suggestions:{action:["Exemple : répondre à ma question de diplôme enregistrée","Écrire ma phrase de candidature enregistrée","Faire le nettoyage de cuisine convenu"],minimum:["Répondre à la même question d’entraînement","Écrire la même phrase utile","Laver les deux mêmes tasses convenues"],cue:["Après avoir débarrassé mon assiette du dîner","À ma pause fixe de 12 h 30","Après notre repas partagé"],place:["À la table de ma cuisine","Au bureau accessible pendant ma pause","À mon évier accessible"],minutes:[2,1],fallback:["Utiliser mes notes accessibles au repas de demain","Dicter la phrase avec mes notes enregistrées","Au prochain créneau de nettoyage convenu, responsabilités couvertes"],observation:["Repère présent, remarqué et action possible","Ce cadre permettait-il la même action ?","Repère présent et tâche convenue possible"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : répondre à ma question de diplôme enregistrée",minimum:"Répondre à la même question d’entraînement",cue:"Après avoir débarrassé mon assiette du dîner",place:"À la table de ma cuisine",fallback:"Utiliser mes notes accessibles au repas de demain",observation:"Repère présent, remarqué et action possible",minutes:2},{action:"Écrire ma phrase de candidature enregistrée",minimum:"Écrire la même phrase utile",cue:"À ma pause fixe de 12 h 30",place:"Au bureau accessible pendant ma pause",fallback:"Dicter la phrase avec mes notes enregistrées",observation:"Ce cadre permettait-il la même action ?",minutes:1},{action:"Faire le nettoyage de cuisine convenu",minimum:"Laver les deux mêmes tasses convenues",cue:"Après notre repas partagé",place:"À mon évier accessible",fallback:"Au prochain créneau de nettoyage convenu, responsabilités couvertes",observation:"Repère présent et tâche convenue possible",minutes:2}]},suggested:{action:"Exemple : répondre à ma question de diplôme enregistrée",minimum:"Répondre à la même question d’entraînement",minutes:2,cueHint:"Après avoir débarrassé mon assiette du dîner",placeHint:"À la table de ma cuisine",obstacleHint:"Exemple : l’ancien repère arrivait sans mes notes",fallbackHint:"Utiliser mes notes accessibles au repas de demain",observationHint:"Repère présent, remarqué et action possible"},stopRule:"Ne pratique pas au volant, ni si cela gêne l’aide à un proche ou la sécurité.",accessibleAlternative:"Utilise un rappel visible ou accessible, des documents audio, une aide convenue ou un autre moment adapté."},result:{question:"Ton repère a-t-il permis de faire le minimum ?",observationPrompt:"Le repère s’est-il présenté ? L’as-tu remarqué ? L’action était-elle possible ?"},judgment:{primary:{id:"motivation-3-usable-setting-decision",scenario:"Leïla veut répondre aujourd’hui à sa question enregistrée. Après avoir déposé son enfant à l’école, elle part travailler : ce repère a échoué. Ce soir, cinq minutes avec ses notes sont confirmées. Sa pause déjeuner fixe permet une copie sur téléphone. Demain, elle pourrait étudier en train, sans départ confirmé.",question:"Quel changement teste le plus directement la même action aujourd’hui ?",options:[{id:"motivation-3-dinner",text:"Utiliser le créneau confirmé du dîner, avec ses notes actuelles, et répondre à la même question enregistrée.",feedback:"Ce choix remplace le créneau indisponible, sans changer l’action ni le matériel. Le temps est confirmé aujourd’hui. Note si le repère se présente, se remarque et permet de répondre."},{id:"motivation-3-phone-copy",text:"Faire une copie sur téléphone à midi, puis répondre à la question lors d’une autre pause disponible.",feedback:"Des notes transportables pourraient faciliter de futures pauses. Mais ce choix utilise le créneau connu pour préparer, sans dater la réponse. Le dîner teste l’action aujourd’hui, avec le matériel disponible."},{id:"motivation-3-train",text:"Emporter les notes pour le train de demain et répondre à la même question une fois le départ confirmé.",feedback:"Le train pourrait convenir après confirmation. Mais ce choix reporte l’essai malgré un créneau disponible aujourd’hui. Si le dîner ne convient plus, confirme la date du train avant de t’engager."}],bestOptionId:"motivation-3-dinner"}},carry:{takeaway:"Un repère utile se présente, se remarque et permet d’agir dans ce cadre.",followUp:{questionId:"motivation-3-return",question:"Quelle condition a manqué : le repère, ton attention ou la possibilité d’agir ?",observationPrompt:"Le repère s’est-il présenté ? L’as-tu remarqué ? L’action était-elle possible ?",adjustmentPrompt:"Quel seul changement rendrait le prochain essai plus adapté ?"}},goDeeper:{sections:[{heading:"Un repère se vérifie dans la pratique",paragraphs:["La revue de Gollwitzer et Sheeran publiée en 2006 rassemble 94 tests indépendants de plans reliant une situation à une action choisie. L’atteinte des objectifs s’améliorait en moyenne. La taille d’effet standardisée historique de 0.65 n’est pas une amélioration de 65 pour cent. Elle ne prédit pas l’effet de ton rappel d’application. Ces moyennes historiques concernent des objectifs et des cadres variés, pas ce repère d’étude précis. [M08]","Wood et Rünger décrivent la répétition liée au contexte comme une composante de l’apprentissage des habitudes. Un repère seul ne garantit pas l’action ; toute routine n’est pas forcément automatique. [M07] Les trois vérifications d’ODA servent à apprendre : présent, remarqué, possible. Elles distinguent un rappel manqué d’un matériel absent ou d’une responsabilité concurrente. Si le repère ne se présente pas, note l’absence d’occasion lorsque c’est pertinent. S’il se présente sans action, note ce fait sans en faire un jugement sur ton engagement."]},{heading:"Soixante-six jours : une estimation par modèle",paragraphs:["L’étude de Lally de 2010 a observé des comportements quotidiens choisis pendant 84 jours. Pour les 39 participants dont les courbes d’automaticité étaient bien ajustées, le délai médian estimé pour atteindre 95 pour cent du plateau était de 66 jours. Les estimations allaient de 18 à 254 jours. La plus longue dépassait la période observée. Ce n’étaient pas des dates constatées de formation d’habitude, rapide, moyenne ou lente. [M05]","Préparer ton diplôme ne reproduit pas les comportements alimentaires ou physiques étudiés. N’utilise pas cette estimation comme échéance, ni comme preuve que la pratique devrait devenir facile. Garde le même essai et examine les occasions disponibles, l’action utile et les conditions qui l’ont permise. Un repère peut convenir en semaine et demander une autre organisation selon tes horaires ou l’aide à un proche. Teste un changement délibéré. Garde les notes précédentes pour comparer des conditions réelles."]}],sourceIds:["M08","M07","M05"]}},{schemaVersion:2,revision:2,id:"motivation-4",courseId:"motivation",locale:"fr",title:"Ton plan coince au même moment ?",goal:"Teste une réponse faisable à l’obstacle observé, en préservant tes besoins et responsabilités.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Étudier au coucher des enfants ? La motivation ne peut pas prendre le relais.",reason:{id:"motivation-4-accepted-change-cost",label:"Quel changement acceptes-tu pour résoudre l’obstacle observé ?",kind:"text",maxLength:160,optional:!0,suggestions:["Déplacer le créneau, garder l’action utile","Demander une aide précise, attendre l’accord","Adapter l’accès plutôt qu’exiger plus d’effort"]},why:{id:"motivation-4-why",label:"Que faut-il préserver pendant que cet objectif avance ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Garde ton objectif et ton action utile. Un essai réel révèle l’obstacle : distraction, matériel absent, aide à un proche ou besoin de santé. Associer résultat, obstacle et réponse montre des bénéfices moyens modestes en recherche. Cela ne crée ni temps ni aide.","Adapte la réponse. Un onglet distrayant peut demander une autre installation. Aider un proche exige un créneau couvert ou une aide convenue. La maladie peut nécessiter du repos. Teste l’action utile ainsi permise au prochain créneau adapté. Répéter prépare, sans prouver que la solution fonctionne."],example:{title:"Leïla profite du relais",text:"Jeudi, l’étude de Leïla tombe au coucher de son enfant. Son conjoint accepte cinq minutes de relais ensuite. Elle déplace la même question, puis répond à la table pendant ce relais convenu. Elle note accord et réponse séparément. Celle-ci doit être retravaillée. Demain reste à confirmer."}},move:{invitation:"Adapte une condition à l’obstacle ; garde l’action utile.",instructions:["Relais convenu : fais la même action ; ajuste seulement l’obstacle observé.","Sans accord : « Adapter ce geste », puis « Soutien ». Précise qui fait quoi, quand.","Refus : créneau disponible ou pause. Note le soutien séparément."],prompts:[{id:"motivation-4-support-request",label:"Quelle tâche demanderais-tu, à qui et quand ?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Exemple : demander par SMS cinq minutes de relais à Camille."}],suggestions:{action:["Exemple : écrire ma phrase de candidature enregistrée","Répondre à ma question pendant le relais convenu","Lire mon passage enregistré avec l’audio"],minimum:["Écrire la même phrase utile de candidature","Répondre à la même question d’entraînement","Écouter le même passage utile"],cue:["Après ma pause de 14 h au travail","Au début des cinq minutes de relais convenues","À ma pause confirmée de 12 h 30"],place:["Sur mon ordinateur de travail","À la table de ma cuisine","Dans mon espace de pause calme et accessible"],minutes:[2,5],fallback:["Couper les alertes facultatives, rester joignable en urgence","Si le relais tombe à l’eau, suspendre l’essai","Demander une version accessible si l’audio échoue"],observation:["Alertes présentes ? Ma réponse a-t-elle permis d’écrire ?","Relais disponible et réponse donnée : deux faits distincts","Accès disponible et passage écouté : deux faits distincts"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : écrire ma phrase de candidature enregistrée",minimum:"Écrire la même phrase utile de candidature",cue:"Après ma pause de 14 h au travail",place:"Sur mon ordinateur de travail",fallback:"Couper les alertes facultatives, rester joignable en urgence",observation:"Alertes présentes ? Ma réponse a-t-elle permis d’écrire ?",minutes:2},{action:"Répondre à ma question pendant le relais convenu",minimum:"Répondre à la même question d’entraînement",cue:"Au début des cinq minutes de relais convenues",place:"À la table de ma cuisine",fallback:"Si le relais tombe à l’eau, suspendre l’essai",observation:"Relais disponible et réponse donnée : deux faits distincts",minutes:2},{action:"Lire mon passage enregistré avec l’audio",minimum:"Écouter le même passage utile",cue:"À ma pause confirmée de 12 h 30",place:"Dans mon espace de pause calme et accessible",fallback:"Demander une version accessible si l’audio échoue",observation:"Accès disponible et passage écouté : deux faits distincts",minutes:5}]},suggested:{action:"Exemple : écrire ma phrase de candidature enregistrée",minimum:"Écrire la même phrase utile de candidature",minutes:2,cueHint:"Après ma pause de 14 h au travail",placeHint:"Sur mon ordinateur de travail",obstacleHint:"Exemple : les alertes facultatives ont interrompu ma dernière phrase",fallbackHint:"Couper les alertes facultatives, rester joignable en urgence",observationHint:"Alertes présentes ? Ma réponse a-t-elle permis d’écrire ?"},stopRule:"Préserve l’aide aux proches et les besoins urgents. Maladie ou danger : choisis soutien ou repos.",accessibleAlternative:"Adapte l’accès ou l’horaire ; choisis aide convenue, soutien ou repos."},result:{question:"Ta réponse a-t-elle permis de faire ton minimum choisi ?",observationPrompt:"L’obstacle s’est-il présenté ? Quelle réponse as-tu utilisée ?"},judgment:{primary:{id:"motivation-4-covered-slot-decision",scenario:"Le créneau de guitare tombe au coucher des enfants. Ce soir, cinq minutes de relais sont confirmées et la guitare est prête. Un voisin pourrait aider davantage samedi, sans accord confirmé. Le parent veut jouer une courte phrase ce soir en préservant les besoins des enfants.",question:"Quelle réponse convient le mieux au prochain essai ?",options:[{id:"motivation-4-confirmed-cover",text:"Jouer la phrase pendant les cinq minutes de relais confirmées ce soir, puis s’arrêter à leur fin.",feedback:"L’accord apporte la condition manquante sans agrandir l’action. Joue la même phrase et distingue pratique et relais. Ce soir ne réserve aucune aide pour les jours suivants."},{id:"motivation-4-saturday-request",text:"Demander au voisin le créneau plus long de samedi et attendre son accord avant de programmer la pratique.",feedback:"Cette demande de soutien est sûre pour plus tard. Elle ne teste pas la phrase possible ce soir. Choisis-la si ce soir ne convient plus. Samedi reste à confirmer."},{id:"motivation-4-prepare-first",text:"Consacrer les cinq minutes de relais de ce soir à vérifier l’accordage et repérer la phrase pour une autre séance.",feedback:"Accorder et repérer peuvent aider à préparer. Ici, instrument et phrase sont prêts. Préparer encore laisse la pratique sans essai. Utilise le relais confirmé pour jouer cette phrase."}],bestOptionId:"motivation-4-confirmed-cover"}},carry:{takeaway:"Une réponse aide si elle correspond à l’obstacle et préserve les besoins réels.",followUp:{questionId:"motivation-4-barrier-response-return",question:"As-tu fait l’action enregistrée ? Le changement a-t-il résolu l’obstacle observé ?",observationPrompt:"Qu’as-tu pratiqué, quel soutien as-tu reçu et quelle contrainte reste présente ?",adjustmentPrompt:"Quel seul changement rendrait le prochain essai plus adapté ?"}},goDeeper:{sections:[{heading:"Planifier aide, mais la durée étudiée compte",paragraphs:["La revue de Wang et collègues de 2021 regroupe 21 articles et 24 effets du contraste mental associé aux intentions de mise en œuvre. L’effet moyen sur l’atteinte des objectifs était faible à modéré. Les résultats variaient selon les objectifs et présentaient des indices de biais de publication. Associer résultat, obstacle et réponse ne garantit aucun souhait. Cela ne montre pas que les pensées changent les événements extérieurs ni que tous les formats WOOP sont équivalents. [M10]","Duckworth et collègues ont testé un protocole scolaire auprès de 77 élèves de cinquième année de primaire, dans une seule école. Trois séances d’une heure en petits groupes comprenaient des exercices répétés et des cartes de rappel. Certains résultats scolaires se sont améliorés, mais les différences ultérieures entre groupes n’étaient pas significatives. [M03] Le bref exercice d’ODA change le public, le soutien et la durée. Il adapte le protocole pour choisir une réponse testable, sans reproduire toute l’intervention. Répète si cela t’aide, puis distingue cette préparation de l’occasion réelle où l’obstacle apparaît et demande une réponse."]},{heading:"Répondre à l’obstacle sans accuser la personne",paragraphs:["La procédure examine un résultat souhaité, un obstacle et une réponse choisie. Elle n’établit pas que tout obstacle viendrait d’une attitude intérieure. Aide à un proche, argent, accès lié au handicap, horaires décalés, maladie ou comportement nuisible d’autrui peuvent limiter les possibilités. Une réponse concrète peut être du soutien convenu, un autre horaire, un aménagement, du repos ou une limite posée. L’adaptation pour adultes doit nommer honnêtement ces contraintes. [M03, M10]","Appuie-toi sur les faits de ton essai pour changer une condition. Si le repère était présent mais le matériel absent, t’engager davantage ne résout pas le problème. Si un proche avait besoin de toi, assure cette responsabilité. Si une habitude distrayante s’est présentée, teste une réponse qui garde les contacts urgents possibles. Sans obstacle rencontré, la solution reste non testée. Note l’action utile séparément de l’aide organisée ou du matériel déplacé. Ensuite, garde l’installation qui fonctionne, au lieu d’accumuler les rituels ou d’exiger une motivation plus forte."]}],sourceIds:["M10","M03"]}},{schemaVersion:2,revision:2,id:"motivation-5",courseId:"motivation",locale:"fr",title:"Une journée manquée ? Prévois une reprise faisable.",goal:"Revois le même essai, garde ce qui aide et date la prochaine tentative.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Séances manquées ? L’objectif a-t-il changé, ou tes disponibilités ?",reason:{id:"motivation-5-reason",label:"Cet objectif mérite-t-il une place la semaine prochaine ?",kind:"text",maxLength:160,optional:!0,suggestions:["Reprendre un objectif que je choisis toujours","Changer un repère qui ne convient plus","Préserver le repos, demander le soutien nécessaire"]},why:{id:"motivation-5-why",label:"Cet objectif mérite-t-il une place la semaine prochaine ?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Revois ta raison, ton minimum utile, ton repère et les faits. Suivre les progrès peut aider en moyenne à atteindre les objectifs. Cela ne transforme ni un plan jamais essayé en action, ni l’absence de notes en échec. Distingue préparation, travail et pause pour voir ce qui aide.","Dans une étude, une occasion manquée n’a pas sensiblement perturbé la formation des habitudes. Cela ne prouve pas les longues interruptions sans effet. Reprends une installation adaptée, change le créneau indisponible ou reconsidère l’objectif. Date la prochaine action. Pas besoin de doubler l’effort ni de mériter le repos."],example:{title:"Leïla prépare la suite",text:"Dimanche, Leïla revoit son plan de diplôme. Le dîner a permis deux essais ; de nouveaux horaires en ont bloqué deux autres. Elle garde l’objectif et place une question lundi, à la pause déjeuner disponible, avec ses notes accessibles. Elle note le créneau. Les séances manquées le restent. Lundi reste prévu."}},move:{invitation:"Relis tes notes ; date la même action utile au créneau disponible.",instructions:["Modifie une condition observée ; confirme date et cadre.","Ce plan prévoit cet essai et le bilan du lendemain. Le bilan hebdomadaire reste facultatif."],prompts:[],suggestions:{action:["Exemple : répondre à ma question de diplôme enregistrée","Faire ma courte marche enregistrée","Faire le nettoyage de cuisine convenu"],minimum:["Répondre à la même question d’entraînement","Parcourir le même trajet sûr de cinq minutes","Laver les deux mêmes tasses convenues"],cue:["À ma pause déjeuner confirmée, 12 h 30","Au début de ma pause fixe de midi","Après notre repas partagé"],place:["Au bureau accessible pendant ma pause","Sur ma boucle accessible près du travail","À mon évier accessible"],minutes:[2,5],fallback:["Pause annulée : dater un autre créneau faisable","Trajet dangereux : choisir un mouvement assis","Si impossible, convenir d’un autre nettoyage utile"],observation:["Le nouveau créneau a-t-il permis la même question ?","Mouvement effectué et temps disponible","Tâche faite et cadre adapté ou non"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : répondre à ma question de diplôme enregistrée",minimum:"Répondre à la même question d’entraînement",cue:"À ma pause déjeuner confirmée, 12 h 30",place:"Au bureau accessible pendant ma pause",fallback:"Pause annulée : dater un autre créneau faisable",observation:"Le nouveau créneau a-t-il permis la même question ?",minutes:2},{action:"Faire ma courte marche enregistrée",minimum:"Parcourir le même trajet sûr de cinq minutes",cue:"Au début de ma pause fixe de midi",place:"Sur ma boucle accessible près du travail",fallback:"Trajet dangereux : choisir un mouvement assis",observation:"Mouvement effectué et temps disponible",minutes:5},{action:"Faire le nettoyage de cuisine convenu",minimum:"Laver les deux mêmes tasses convenues",cue:"Après notre repas partagé",place:"À mon évier accessible",fallback:"Si impossible, convenir d’un autre nettoyage utile",observation:"Tâche faite et cadre adapté ou non",minutes:2}]},suggested:{action:"Exemple : répondre à ma question de diplôme enregistrée",minimum:"Répondre à la même question d’entraînement",minutes:2,cueHint:"À ma pause déjeuner confirmée, 12 h 30",placeHint:"Au bureau accessible pendant ma pause",obstacleHint:"Exemple : mon changement d’horaires noté a supprimé l’étude du soir",fallbackHint:"Pause annulée : dater un autre créneau faisable",observationHint:"Le nouveau créneau a-t-il permis la même question ?"},stopRule:"Une perte d’intérêt persistante ou des difficultés au quotidien justifient du soutien maintenant. Danger immédiat : aide urgente.",accessibleAlternative:"Documents accessibles, aide convenue, demande de soutien, repos ou pause explicite : à toi de choisir."},result:{question:"As-tu fait la reprise que tu avais choisie ?",observationPrompt:"Quelle action, quel soutien ou quelle pause as-tu noté ?"},judgment:{primary:{id:"motivation-5-recorded-barrier-decision",scenario:"Les nouveaux horaires de Karim commencent pendant le dîner, supprimant sa marche du soir. Marcher compte toujours pour lui. Un trajet sûr de cinq minutes existe chaque midi. Avant le travail, il faudrait se lever plus tôt ; une longue marche est possible dimanche. Il veut reprendre en semaine sans réduire son sommeil.",question:"Quel plan respecte l’obstacle observé et l’effort accepté ?",options:[{id:"motivation-5-early-walk",text:"Marcher avant sa prise de poste et avancer le réveil pour préserver ce créneau.",feedback:"Le trajet avant le travail résout le conflit du soir, mais avancer le réveil contredit sa limite sur le sommeil. Le midi permet une reprise en semaine sans ce coût supplémentaire."},{id:"motivation-5-sunday-walk",text:"Choisir une marche plus longue le dimanche et vérifier si ce rythme convient mieux à ses horaires.",feedback:"Une marche hebdomadaire serait une révision faisable, pas un échec. Karim veut tester une reprise en semaine, et le midi est disponible. Essaie cette condition avant de changer le rythme."},{id:"motivation-5-lunch-return",text:"Dater la prochaine pause déjeuner, marcher cinq minutes sur le trajet sûr et noter si l’horaire convient.",feedback:"Ce choix garde la marche et son unité utile, en remplaçant le soir indisponible. Seule la marche réelle compte comme pratique. Le bilan du lendemain aidera à garder, modifier ou arrêter cette organisation."}],bestOptionId:"motivation-5-lunch-return"}},carry:{takeaway:"Garde ta raison et l’action utile ; change la condition qui a échoué dans tes essais.",followUp:{questionId:"motivation-5-return",question:"Le nouveau créneau a-t-il convenu ? L’objectif vaut-il encore l’effort la semaine prochaine ?",observationPrompt:"Quelle action, quel soutien ou quelle pause as-tu noté ?",adjustmentPrompt:"Quel seul changement rendrait le prochain essai plus adapté ?"}},goDeeper:{sections:[{heading:"Faire le bilan sans inventer une série de réussites",paragraphs:["La revue de Harkin et collègues rassemble 138 études randomisées. Elle trouve un bénéfice moyen du suivi des progrès sur l’atteinte des objectifs. Les buts et méthodes variaient. Noter et communiquer les résultats étaient associés à des effets plus grands. Cela ne démontre pas qu’un partage public ou un rythme hebdomadaire soit nécessaire. Le bilan du lendemain proposé par ODA est une adaptation, pas une durée validée. Le bilan hebdomadaire reste facultatif et ce plan ne le programme pas automatiquement. [M13]","Dans l’étude observationnelle de Lally, une occasion manquée n’a pas sensiblement perturbé le processus de formation d’habitude modélisé. Ce résultat limité ne prouve pas qu’une longue interruption laisse l’habitude intacte. [M05] Appuie-toi sur tes essais pour choisir la suite. Garde une unité utile, change le repère ou la réponse inadaptés et laisse les occasions manquées visibles. Un plan futur reste un plan. Si l’objectif ne vaut plus le temps demandé, adapte-le, reporte-le ou arrête-le délibérément. Terminer l’apprentissage reste distinct de faire l’action et d’en tirer un bilan."]},{heading:"Le plaisir reste facultatif, le soutien est disponible",paragraphs:["Cette dernière leçon fait le bilan du même essai, sans ajouter un nouveau rituel de motivation. Les recherches soutiennent en moyenne l’intérêt de comparer les progrès réels à un objectif choisi. Elles n’identifient pas la meilleure technique pour chaque personne. Tes notes peuvent montrer un repère indisponible, du matériel absent ou un temps demandé devenu inadapté. Pars de cette condition observée pour choisir un changement. Ne compte pas une préparation ou une promesse comme l’action elle-même. [M13]","Ne conditionne pas le repos de base ou toutes les activités agréables à la productivité. Si tu choisis ensuite un audio gratuit et compatible, reste attentif à la circulation et à la sécurité. Perte d’intérêt persistante, détresse, épuisement ou difficultés à accomplir les activités habituelles peuvent demander une évaluation professionnelle. Le NIMH recommande de demander du soutien et une aide immédiate en cas de danger urgent. Il ne diagnostique pas la cause d’un manque de motivation et n’impose pas d’attendre avant de demander de l’aide. [M20] Pendant ce temps, tu peux garder une petite pratique utile, demander du soutien ou faire une pause."]}],sourceIds:["M13","M05","M20"]}}];function n(e,a,u){const s=e.judgment.primary,t=[...s.options],o=t.findIndex(r=>r.id===s.bestOptionId);return[t[a],t[o]]=[t[o],t[a]],{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.instructions[1],"Note les faits. Demain, fais le bilan du même essai."],reflection:e.direction.reason.label,question:`${s.scenario} ${s.question}`,options:t.map(r=>r.text),correct:a,feedback:t[a].feedback,takeaway:e.carry.takeaway,sources:e.goDeeper.sourceIds,photo:u}}const c={id:"motivation",title:"Pas motivé ? Fais une place à ton objectif.",subtitle:"Cinq leçons pour choisir un objectif qui vaut l’effort, essayer un minimum utile et adapter ton organisation à ta semaine.",description:"Choisis ce que ton effort doit servir. Fais une petite action utile, puis ajuste le repère ou le soutien à partir des faits.",scope:"Un apprentissage pour les objectifs du quotidien. Un manque d’élan constant, l’épuisement ou des difficultés à fonctionner peuvent dépasser la motivation. Tu peux demander du soutien. Un professionnel de santé peut t’aider à en comprendre la cause.",outcome:"Une action choisie et une prochaine tentative datée, adaptées à ce que tes essais ont montré.",photo:{id:"1790004245013-b347139d5591",alt:"Un homme court sur un chemin forestier ensoleillé"},lang:"fr",lessons:[n(i[0],1,{id:"1517971129774-8a2b38fa128e",alt:"Une femme écrit dans un carnet près d’une fenêtre"}),n(i[1],2,{id:"1581578731509-8ae9c5a3e7d3",alt:"Une paire de chaussures près d’une porte"}),n(i[2],2,{id:"1499933374294-4584851497cc",alt:"Un réveil noir posé sur une table"}),n(i[3],1,{id:"1575478004055-999ebe26dab7",alt:"Une femme marche sous la pluie avec un parapluie"}),n(i[4],0,{id:"1577950248429-7530424d9682",alt:"Un calendrier mensuel épinglé sur un panneau"})]},d=Object.freeze(Object.defineProperty({__proto__:null,COURSE:c,LESSONS_V2:i,SOURCES:l},Symbol.toStringTag,{value:"Module"}));export{d as m};
